class RestAPI:
    def __init__(self, database=None):
        self._users = {}
        self._net = {}
        records = []
        if isinstance(database, dict):
            records = database.get("users", [])
        elif database:
            records = list(database)
        for record in records:
            name = record["name"]
            self._register(name)
            for other, amount in record.get("owes", {}).items():
                self._book(other, name, amount)
            for other, amount in record.get("owed_by", {}).items():
                self._book(name, other, amount)

    def get(self, url, payload=None):
        if url != "/users":
            raise ValueError("unknown url: " + str(url))
        payload = payload or {}
        names = payload.get("users")
        if names is None:
            return {"users": [self._user(name) for name in self._users]}
        return {"users": [self._user(name) for name in sorted(names)]}

    def post(self, url, payload=None):
        payload = payload or {}
        if url == "/add":
            name = payload["user"]
            self._register(name)
            return self._user(name)
        if url == "/iou":
            lender = payload["lender"]
            borrower = payload["borrower"]
            self._register(lender)
            self._register(borrower)
            self._book(lender, borrower, payload["amount"])
            return {"users": [self._user(n) for n in sorted([lender, borrower])]}
        raise ValueError("unknown url: " + str(url))

    def _register(self, name):
        self._users.setdefault(name, None)
        self._net.setdefault(name, {})

    # Ledger: self._net[a][b] > 0 means b owes a that much. Counterparties
    # seen only in a seeded balance are tracked here but never listed.
    def _book(self, creditor, debtor, amount):
        if creditor == debtor:
            return
        credit_line = self._net.setdefault(creditor, {})
        debt_line = self._net.setdefault(debtor, {})
        credit_line[debtor] = self._clean(credit_line.get(debtor, 0.0) + amount)
        debt_line[creditor] = self._clean(debt_line.get(creditor, 0.0) - amount)
        self._drop_zero(creditor, debtor)
        self._drop_zero(debtor, creditor)

    @staticmethod
    def _clean(value):
        return float(round(value, 10))

    def _drop_zero(self, holder, other):
        if abs(self._net[holder].get(other, 0.0)) < 1e-9:
            self._net[holder].pop(other, None)

    def _user(self, name):
        ledger = self._net.get(name, {})
        owes = {}
        owed_by = {}
        for other, signed in sorted(ledger.items()):
            if signed < 0:
                owes[other] = -signed
            elif signed > 0:
                owed_by[other] = signed
        return {
            "name": name,
            "owes": owes,
            "owed_by": owed_by,
            "balance": self._clean(sum(ledger.values())),
        }
